                name="fullName"
                type="text"
                autocomplete="name"
                required
                aria-describedby="full-name-error"
              />
              <p class="error-text" id="full-name-error" hidden></p>
            </div>

            <div class="form-field">
              <label for="email-address">
                Email address <span class="required-marker" aria-hidden="true">*</span>
              </label>
              <input
                id="email-address"
                name="email"
                type="email"
                autocomplete="email"
                required
                aria-describedby="email-address-error"
              />
              <p class="error-text" id="email-address-error" hidden></p>
            </div>

