    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content">
      <div class="page-shell">
        <header class="hero">
          <p class="eyebrow">Support</p>
          <h1>Contact our support team</h1>
          <p class="subtitle">Send your details and we will get back to you as soon as possible.</p>
        </header>

        <section class="card" aria-labelledby="contact-form-title">
          <h2 id="contact-form-title" class="sr-only">Contact form</h2>
          <form id="support-form" novalidate>
            <div class="form-field">
              <label for="full-name">
                Full name <span class="required-marker" aria-hidden="true">*</span>
              </label>
              <input
                id="full-name"
                name="fullName"
                type="text"
                autocomplete="name"
                required
                aria-describedby="full-name-error"
              />
              <p class="error-text" id="full-name-error" hidden></p>
            </div>

            <div class="form-field">
              <label for="email-address">
                Email address <span class="required-marker" aria-hidden="true">*</span>
              </label>
              <input
                id="email-address"
                name="email"
                type="email"
                autocomplete="email"
                required
                aria-describedby="email-address-error"
              />
              <p class="error-text" id="email-address-error" hidden></p>
            </div>

            <div class="form-field">
              <label for="phone-number">Phone number</label>
              <input
                id="phone-number"
                name="phone"
                type="tel"
                autocomplete="tel"
                placeholder="+1 555 123 4567"
                aria-describedby="phone-number-help"
              />
              <p class="help-text" id="phone-number-help">Use a format like +1 555 123 4567 or 555-123-4567.</p>
            </div>

            <p class="status" id="form-status" aria-live="polite"></p>

            <div class="actions">
              <button type="submit">Send message</button>
            </div>
          </form>
        </section>
      </div>
    </main>

    <script>
      const form = document.getElementById("support-form");
      const status = document.getElementById("form-status");
      const fields = [
        {
          input: document.getElementById("full-name"),
          error: document.getElementById("full-name-error"),
          message: "Please enter your full name.",
        },
        {
          input: document.getElementById("email-address"),
          error: document.getElementById("email-address-error"),
          message: "Please enter a valid email address.",
        },
      ];

      function setFieldError(field, message) {
        field.input.setAttribute("aria-invalid", "true");
        field.error.textContent = message;
        field.error.hidden = false;
      }

      function clearFieldError(field) {
        field.input.removeAttribute("aria-invalid");
        field.error.textContent = "";
        field.error.hidden = true;
      }

      function validateForm() {
        let firstInvalid = null;

        fields.forEach((field) => {
          const value = field.input.value.trim();
          const valid = field.input.validity.valid && value.length > 0;

          if (!valid) {
            if (!firstInvalid) {
              firstInvalid = field.input;
            }
            setFieldError(field, field.message);
          } else {
            clearFieldError(field);
          }
        });

        return firstInvalid;
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        status.textContent = "";
        status.removeAttribute("data-state");

        const firstInvalid = validateForm();

        if (firstInvalid) {
          firstInvalid.focus();
          return;
        }

        status.textContent = "Thanks — your message is ready to send.";
        status.setAttribute("data-state", "success");
        form.reset();
      });

      fields.forEach((field) => {
        field.input.addEventListener("input", () => {
          if (field.input.value.trim() && field.input.validity.valid) {
            clearFieldError(field);
          }
        });
      });
    </script>
  </body>
</html>
